import { useRouter } from 'next/router'
import { useCallback, useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { apiFetch } from '@/lib/api-client'
import { ApiError } from '@/lib/http'
import { Sidebar } from './Sidebar'

export type CurrentUser = {
  id: string
  email: string
  name: string
  goal: string | null
  subscriptionTier: string
}

interface AppShellProps {
  children: ReactNode
}

export function AppShell({ children }: AppShellProps) {
  const router = useRouter()
  const [user, setUser] = useState<CurrentUser | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let active = true
    apiFetch<CurrentUser>('/api/auth/me')
      .then((me) => {
        if (active) setUser(me)
      })
      .catch((error: unknown) => {
        if (!(error instanceof ApiError) || error.status !== 401) {
          console.error('Could not load the current user')
        }
        if (active) router.replace('/login')
      })
      .finally(() => {
        if (active) setLoading(false)
      })
    return () => {
      active = false
    }
  }, [router])

  const signOut = useCallback(() => {
    void apiFetch<{ success: boolean }>('/api/auth/logout', { method: 'POST' }).finally(() => {
      router.push('/login')
    })
  }, [router])

  if (loading) {
    return <div className="p-8 text-slate-400">Loading your dashboard…</div>
  }

  if (!user) return null

  return (
    <div className="flex min-h-screen">
      <Sidebar tier={user.subscriptionTier} onSignOut={signOut} />
      <main className="flex-1 px-8 py-6">
        <h1 className="mb-6 font-display text-2xl text-white">Welcome back, {user.name}</h1>
        {children}
      </main>
    </div>
  )
}
